/// <summary>A file to attach: the original filename, its media type, and the raw bytes.</summary>
public sealed record AttachmentFile(string FileName, string ContentType, byte[] Content);

/// <summary>One attachment bean from Jira's upload response.</summary>
public sealed record UploadedAttachment(string Id, string Filename, long Size, string MimeType, string ContentUrl);

/// <summary>
/// Outcome of an upload. Jira's response array covers only the files it stored,
/// so anything sent but absent from the response surfaces in <see cref="Missing"/>
/// instead of being silently dropped.
/// </summary>
public sealed class UploadReport
{
    /// <summary>Stored attachments, in Jira's response order.</summary>
    public IReadOnlyList<UploadedAttachment> Uploaded { get; }

    /// <summary>Filenames that were sent but did not come back, in sent order.</summary>
    public IReadOnlyList<string> Missing { get; }

    public bool HasMissing => Missing.Count > 0;

    /// <summary>Sum of the stored attachments' size fields as reported by Jira.</summary>
    public long TotalBytes
    {
        get
        {
            long total = 0;
            foreach (var attachment in Uploaded) total += attachment.Size;
            return total;
        }
    }

    public UploadReport(IReadOnlyList<UploadedAttachment> uploaded, IReadOnlyList<string> missing)
    {
        Uploaded = uploaded;
        Missing = missing;
    }
}
