namespace JiraFiles;

/// <summary>
/// A failure answered by the Jira REST API, decoded from the standard
/// ErrorCollection payload ({errorMessages, errors}). Response text is
/// untrusted: every string is scrubbed of credential material before it can
/// reach <see cref="Exception.Message"/> or <see cref="Messages"/>.
/// </summary>
public sealed class JiraApiError : Exception
{
    public int StatusCode { get; }
    public IReadOnlyList<string> Messages { get; }

    private JiraApiError(int statusCode, IReadOnlyList<string> messages)
        : base(Format(statusCode, messages))
    {
        StatusCode = statusCode;
        Messages = messages;
    }

    private static string Format(int statusCode, IReadOnlyList<string> messages) =>
        messages.Count == 0
            ? $"Jira API request failed with HTTP status {statusCode}."
            : $"Jira API request failed with HTTP status {statusCode}: {string.Join(" | ", messages)}";

    /// <summary>Builds an error from client-side text; each message is redacted first.</summary>
    internal static JiraApiError Create(
        int statusCode, IEnumerable<string> messages, IReadOnlyList<string> secrets)
    {
        var redacted = new List<string>();
        foreach (string message in messages)
        {
            string clean = Redact(message, secrets);
            if (!string.IsNullOrWhiteSpace(clean)) redacted.Add(clean);
        }
        return new JiraApiError(statusCode, redacted);
    }

    /// <summary>Decodes a non-success HTTP response into an error, redacting as it goes.</summary>
    internal static async Task<JiraApiError> FromResponseAsync(
        HttpResponseMessage response, IReadOnlyList<string> secrets)
    {
        string body = "";
        try { body = await response.Content.ReadAsStringAsync().ConfigureAwait(false); }
        catch { /* an unreadable error body still yields the status code */ }

        var messages = new List<string>();
        try
        {
            using var doc = JsonDocument.Parse(body);
            if (doc.RootElement.ValueKind == JsonValueKind.Object)
            {
                if (doc.RootElement.TryGetProperty("errorMessages", out var errorMessages)
                    && errorMessages.ValueKind == JsonValueKind.Array)
                {
                    foreach (var message in errorMessages.EnumerateArray())
                        if (message.ValueKind == JsonValueKind.String)
                            messages.Add(message.GetString()!);
                }
                if (doc.RootElement.TryGetProperty("errors", out var errors)
                    && errors.ValueKind == JsonValueKind.Object)
                {
                    foreach (var field in errors.EnumerateObject())
                        if (field.Value.ValueKind == JsonValueKind.String)
                            messages.Add($"{field.Name}: {field.Value.GetString()}");
                }
            }
        }
        catch (JsonException)
        {
            // Not an ErrorCollection; fall through to the raw-body fallback.
        }

        if (messages.Count == 0 && !string.IsNullOrWhiteSpace(body))
        {
            string text = body.Trim();
            if (text.Length > 500) text = text[..500];
            messages.Add(text);
        }

        return Create((int)response.StatusCode, messages, secrets);
    }

    private static string Redact(string text, IReadOnlyList<string> secrets)
    {
        foreach (string secret in secrets)
            if (!string.IsNullOrEmpty(secret))
                text = text.Replace(secret, "[redacted]", StringComparison.OrdinalIgnoreCase);
        return text;
    }
}
"}

